if __name__ == "__main__":
    import json, random, pathlib
    root = pathlib.Path(__file__).resolve().parent.parent
    rows = []
    for track in ["ADM", "CSP", "DAT", "DMK"]:
        banks = {**SHARED, **TRACK[track]}
        for key, qs in banks.items():
            assert len(qs) >= 10, (track, key, len(qs))
            for i, (q, opts) in enumerate(qs, 1):
                assert len(opts) == 4
                rnd = random.Random(f"{track}-{key}-{i}")
                order = list(range(4)); rnd.shuffle(order)
                o = [opts[j] for j in order]; a = order.index(0)
                rows.append((track, key, i, q, o, a))
    def lit(s):
        assert ";" not in s and "$q$" not in s, s
        return "$q$" + s + "$q$"
    out = ["-- Question banks (generated by dev/quiz_bank.py). Each quiz draws 5 questions per student.",
           "delete from quiz_bank;",
           "insert into quiz_bank(track_code, key, qid, q, o, a) values"]
    out.append(",\n".join(f"({lit(t)},{lit(k)},{i},{lit(q)},array[{','.join(lit(x) for x in o)}],{a})" for t, k, i, q, o, a in rows) + ";")
    out.append("select count(*) || ' questions in the bank' as done from quiz_bank;")
    (root / "supabase/19b_quiz_bank.sql").write_text("\n".join(out) + "\n")
    print(len(rows), "questions")
